import Crypto
import Foundation
import Testing
@testable import ArrowKit

struct AppcastTests {
    /// Same shape as the appcast generated by `server/` (internal/updates).
    private let appcast = Data("""
    <?xml version="1.0" encoding="UTF-8"?>
    <rss version="2.0" xmlns:sparkle="http://www.andymatuschak.org/xml-namespaces/sparkle">
      <channel>
        <item>
          <title>Version 1.2.0</title>
          <sparkle:version>120</sparkle:version>
          <sparkle:shortVersionString>1.2.0</sparkle:shortVersionString>
          <sparkle:minimumSystemVersion>15.0</sparkle:minimumSystemVersion>
          <enclosure url="https://example.com/Arrow-1.2.0.zip" length="4" type="application/octet-stream" sparkle:edSignature="SIG=="></enclosure>
        </item>
        <item>
          <sparkle:version>110</sparkle:version>
          <sparkle:shortVersionString>1.1.0</sparkle:shortVersionString>
          <enclosure url="https://example.com/Arrow-1.1.0.zip" length="8"></enclosure>
        </item>
      </channel>
    </rss>
    """.utf8)

    @Test func parsesItems() {
        let items = Appcast.parse(appcast)
        #expect(items.count == 2)
        #expect(items[0] == AppcastItem(version: "120", shortVersion: "1.2.0", url: "https://example.com/Arrow-1.2.0.zip",
                                        length: 4, edSignature: "SIG==", minimumSystemVersion: "15.0"))
    }

    @Test func picksTheNewestNewerRelease() {
        let items = Appcast.parse(appcast)
        #expect(Appcast.latest(in: items, currentShortVersion: "1.0.0", currentVersion: "100")?.shortVersion == "1.2.0")
        #expect(Appcast.latest(in: items, currentShortVersion: "1.2.0", currentVersion: "120") == nil)
        #expect(Appcast.latest(in: items, currentShortVersion: "1.2.0", currentVersion: "119")?.version == "120")
        #expect(Appcast.latest(in: items, currentShortVersion: "1.10.0", currentVersion: "1") == nil)
    }

    @Test func verifiesEdDSASignatures() {
        let key = Curve25519.Signing.PrivateKey()
        let archive = Data("update archive".utf8)
        let signature = try! key.signature(for: archive).base64EncodedString()
        let publicKey = key.publicKey.rawRepresentation.base64EncodedString()
        let item = AppcastItem(version: "2", shortVersion: "2.0", url: "u", length: archive.count, edSignature: signature)

        #expect(Appcast.verify(archive: archive, item: item, publicKey: publicKey))
        // Tampered archive, wrong length, other key, missing signature.
        #expect(!Appcast.verify(archive: Data("update archivE".utf8), item: item, publicKey: publicKey))
        var wrongLength = item
        wrongLength.length = 3
        #expect(!Appcast.verify(archive: archive, item: wrongLength, publicKey: publicKey))
        let otherKey = Curve25519.Signing.PrivateKey().publicKey.rawRepresentation.base64EncodedString()
        #expect(!Appcast.verify(archive: archive, item: item, publicKey: otherKey))
        var unsigned = item
        unsigned.edSignature = nil
        #expect(!Appcast.verify(archive: archive, item: unsigned, publicKey: publicKey))
    }
}
